import {downloadReport} from './reports.js';
import {getAccount} from './accounts.js';
import {prepareRecognition,retryDelay} from './speech-service.js';
import {createMicInput} from './microphone.js';
import {createLibraryUI} from './library.js';
import {newGame,derive,parseCommand,applyPlan,commit,undo,formatTime,periodLabel,lengthFor,configPlan,playerPlan,currentClock,materializeClock,describe,validateImport,emptyStats} from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let libraryUI=null;let micInput=null;let voiceBatch=null,voiceBatchTimer=null;
let accountUser=null,KEY='';let state=newGame(),saveError='',badBackup=null;
let selected=null,view='live',boxTeam='home',boxPeriod='all',pending=[],mic=null,wantsMic=false,idleMicLabel='MIC OFF',micErrors=0,restartTimer=null,retryWatchdog=null,wake=null,installPrompt=null;
function writeLocal(){if(!accountUser)return;try{if(badBackup)throw Error('Recovery copy needs attention.');localStorage.setItem(KEY,JSON.stringify(state));saveError='';$('#saveStatus').textContent='Local backup saved';}catch(e){saveError=badBackup?saveError:'Autosave failed. Export a backup now to protect this game.';$('#saveStatus').textContent='Not saved · export backup';}}
function save(){writeLocal();libraryUI?.queue();}
function feedback(t,error=false){$('#feedback').textContent=t;$('#feedback').className=error?'error':'success';}
function act(plan,raw='Manual control'){if(!accountUser)return {ok:false,error:'Sign in first.'};try{const wasFinal=state.clock.final;const result=applyPlan(state,plan,raw);save();render();showUnderstood(plan,raw);if(state.clock.final){stopMic();pending=[];renderPending();setView('box');}feedback(result);if(!wasFinal&&state.clock.final&&state.meta?.pdfScope!=='off')makePDF(state.meta?.pdfScope||'team');return {ok:true,message:result};}catch(e){feedback(e.message,true);return {ok:false,error:e.message};}}
function command(raw,voice=false,confidence=1){$('#heard').textContent=`Last heard: “${raw}”`;if(voice&&/^confirm(?: last)?[.!]?$/i.test(raw.trim())&&pending.length){acceptPending(0);return {ok:true,message:'Confirmed pending command'};}if(voice&&/^cancel[.!]?$/i.test(raw.trim())&&pending.length){pending.shift();renderPending();return {ok:true,message:'Cancelled pending command'};}if(pending.length){feedback('Confirm, correct, or cancel the waiting play before recording another.',true);return {ok:false,pending:true};}try{const plan=parseCommand(raw,state);if(plan.confirm||(voice&&($('#reviewAll').checked||confidence<.75))){pending.push({raw,plan});renderPending();showUnderstood(plan,raw);stopMic('REVIEW PLAY');feedback('Check the parsed plays and choose any missing details below.');return {ok:true,pending:true};}return act(plan,raw);}catch(e){feedback(e.message,true);return {ok:false,error:e.message};}}
function showUnderstood(plan,raw){const d=derive(state),el=$('#understood');el.hidden=false;el.innerHTML=`<summary>Understood ${plan.events?.filter(e=>e.type!=='NARRATION_CONTEXT').length||0} events ${plan.choices?.some(c=>!c.resolved)?'· needs your review':''}</summary><p class="muted">“${esc(raw)}”</p>${subPreview(plan)}<ol>${(plan.events||[]).map(e=>`<li>${esc(describe(e,d))}${plan.choices?.some(c=>c.eventId===e.id&&!c.resolved)?' — choose type below':''}</li>`).join('')}</ol>${plan.waitingLabel?`<p>${esc(plan.waitingLabel)}</p>`:''}${(plan.notes||[]).map(n=>`<p class="muted">${esc(n)}</p>`).join('')}`;}
function renderPending(){$('#pending').innerHTML=pending.map((p,i)=>`<div class="pendingRow"><p><strong>Review these plays</strong></p><small>${esc(p.raw)}</small>${(p.plan.notes||[]).map(n=>`<p class="warning">${esc(n)}</p>`).join('')}${subPreview(p.plan)}<ol>${(p.plan.events||[]).map(e=>`<li>${esc(describe(e,derive(state)))}</li>`).join('')}</ol>${(p.plan.choices||[]).map((c,j)=>`<label>${esc(c.label)}<select data-choice="${i}:${j}" aria-label="${esc(c.label)}"><option value="">Choose…</option>${(c.kind==='shot'?[['2','Two points'],['3','Three points'],['1','Free throw']]:[['oreb','Offensive rebound'],['dreb','Defensive rebound']]).map(([v,t])=>`<option value="${v}" ${c.resolved===v?'selected':''}>${t}</option>`).join('')}</select></label>`).join('')}${p.plan.events?.some(e=>e.type==='GAME_END')?reportControls(true):''}<div class="actions"><button class="primary" data-confirm="${i}" ${p.plan.choices?.some(c=>!c.resolved)?'disabled':''}>Confirm</button><button data-correct="${i}">Correct</button><button data-cancel="${i}">Cancel</button></div></div>`).join('');bindReports();$('#pending').querySelectorAll('[data-choice]').forEach(el=>el.onchange=()=>{const [i,j]=el.dataset.choice.split(':').map(Number),p=pending[i],c=p.plan.choices[j],e=p.plan.events.find(e=>e.id===c.eventId);c.resolved=el.value;if(el.value){if(c.kind==='shot'){e.value=+el.value;e.points=e.value*e.made;if(p.plan.context?.lastShot?.id===e.id)p.plan.context.lastShot.value=e.value;if(e.value===1){const ids=p.plan.events.filter(a=>a.autoAssist&&a.shotId===e.id).map(a=>a.id);p.plan.events=p.plan.events.filter(a=>!ids.includes(a.id));p.plan.context.freeShooter=e.playerId;}}else e.stat=el.value;}renderPending();});$('#pending').querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>acceptPending(+b.dataset.confirm));$('#pending').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{pending.splice(+b.dataset.cancel,1);renderPending();$('#understood').hidden=true;feedback('Cancelled; no events added.');});$('#pending').querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>{const p=pending.splice(+b.dataset.correct,1)[0];$('#command').value=p.raw;$('#command').focus();renderPending();});}
function acceptPending(i){const p=pending[i];if(!p)return;p.plan.confirmed=true;if(p.plan.choices?.some(c=>!c.resolved)){feedback('Choose the missing shot or rebound type first.',true);return;}if(p.plan.events?.some(e=>e.type==='GAME_END')){const c=currentClock(state);p.plan.events=p.plan.events.map(e=>({...e,period:c.period,clock:c.seconds}));}if(act(p.plan,p.raw).ok)pending.splice(i,1);renderPending();}
function setView(tab){view=tab;document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==tab);document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('active',n.dataset.tab===tab));if(tab==='setup')renderSetup();if(tab==='box')renderBox();if(tab==='timeline')renderTimeline();}
document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.onclick=()=>setView(b.dataset.tab||b.dataset.go));
function render(){const d=derive(state),c=d.clock;$('#homeName').textContent=d.settings.home+(d.settings.designation==='away'?' · Away':' · Home');$('#awayName').textContent=d.settings.away;$('#homeScore').textContent=d.score.home;$('#awayScore').textContent=d.score.away;$('#homeTimeouts').textContent=`${d.timeouts.home} timeouts left`;$('#awayTimeouts').textContent=`${d.timeouts.away} timeouts left`;$('#period').textContent=c.final?'FINAL':!c.started?'PRE-GAME':periodLabel(c.period,d.settings)+(c.break?(c.period===2&&d.settings.periods===4?' · HALFTIME':' · BREAK'):'');$('#clock').textContent=formatTime(c.seconds);$('#officialClockState').textContent=c.final||c.break||!c.started||c.officialRunning===false?'CLOCK: STOPPED':'CLOCK: RUNNING';$('#toggleClock').textContent=c.final?'Final':c.started?'Game started':'Start game';$('#toggleClock').disabled=c.started||c.final;const unclocked=d.timeline.filter(e=>e.awaitingClock).length;$('#clockStatus').textContent=unclocked?`${unclocked} events waiting for a time. Say “now it’s Q2 3:43” to update the timeline and minutes.`:'Report the scoreboard time to space plays evenly since the last update. The clock does not count down.';$('#lineupCount').textContent=`${d.lineups.home.size} / 5`;$('#warnings').innerHTML=[saveError,...d.warnings].filter(Boolean).map(w=>`<div class="warning">${esc(w)}</div>`).join('');const cards=on=>d.roster.filter(p=>p.team==='home'&&d.players[p.id].onCourt===on).map(p=>{const pl=d.players[p.id];return `<button class="player ${on?'':'bench'}" data-player="${esc(p.id)}"><span class="jersey">${esc(p.number)}</span><span class="name">${esc(p.first)} ${esc(p.last)}</span><span class="numbers"><span>${formatTime(pl.minutes)}<small>MIN</small></span><span>${pl.stats.pts}<small>PTS</small></span><span>${pl.stats.pf}<small>PF</small></span></span></button>`;}).join('');$('#floor').innerHTML=cards(true)||'<div class="empty panel">Add your roster and choose five starters in Game setup.<div class="actions"><button id="goSetup">Set up game →</button></div></div>';$('#bench').innerHTML=cards(false)||'<p class="muted">No players on the bench.</p>';$('#goSetup')?.addEventListener('click',()=>setView('setup'));document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{selected=b.dataset.player;renderQuick();});if(selected)renderQuick();if(view==='box')renderBox();if(view==='timeline')renderTimeline();}
function renderQuick(){const d=derive(state),p=d.players[selected];if(!p){$('#quick').hidden=true;return;}$('#quick').hidden=false;const stats=[['2PT made','shot',2,1],['2PT missed','shot',2,0],['3PT made','shot',3,1],['3PT missed','shot',3,0],['FT made','shot',1,1],['FT missed','shot',1,0],['O rebound','oreb'],['D rebound','dreb'],['Assist','ast'],['Steal','stl'],['Block','blk'],['Turnover','to'],['Foul','pf']];$('#quick').innerHTML=`<div class="sectionhead"><h2>#${esc(p.number)} ${esc(p.first)} ${esc(p.last)}</h2><button id="closeQuick" aria-label="Close player controls">×</button></div><div class="actions">${(p.onCourt?stats:[]).map((s,i)=>`<button data-stat="${i}">${s[0]}</button>`).join('')}<button id="subPlayer" class="primary">${p.onCourt?'Substitute out':'Check in'}</button><button id="playerReport">Player report</button></div>`;$('#closeQuick').onclick=()=>{selected=null;$('#quick').hidden=true;};$('#quick').querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{const s=stats[+b.dataset.stat];if(state.clock.final)return feedback('Undo finalization before making changes.',true);act({events:[s[1]==='shot'?{type:'SHOT',value:s[2],made:s[3],attempts:1,points:s[2]*s[3],playerId:p.id,team:p.team}:{type:'STAT',stat:s[1],playerId:p.id,team:p.team}],clock:s[1]==='pf'?{running:false}:{},label:`#${p.number} · ${s[0]}`});});$('#subPlayer').onclick=()=>subDialog(p);$('#playerReport').onclick=()=>{const periods=Array.from({length:Math.max(d.settings.periods,d.clock.period)},(_,i)=>i+1);showDialog(`<h2>#${esc(p.number)} ${esc(p.first)} ${esc(p.last)}</h2><div class="tablewrap">${statsTable(periods.map(q=>({label:periodLabel(q,d.settings),min:p.periodMinutes[q]||0,stats:p.periodStats[q]||emptyStats()})))}</div><h3 style="margin-top:20px">Playing intervals</h3>${p.intervals.map(i=>`<p>${periodLabel(i.period,d.settings)} · ${formatTime(i.in)} → ${formatTime(i.out)} = ${formatTime(i.seconds)}</p>`).join('')||'<p>No playing time yet.</p>'}`);};}
function subDialog(p){const d=derive(state),other=d.roster.filter(q=>q.team===p.team&&q.id!==p.id&&d.players[q.id].onCourt!==p.onCourt);showDialog(`<h2>${p.onCourt?'Substitute':'Check in'} #${esc(p.number)} ${esc(p.first)}</h2><form id="subForm" class="fields"><label>${p.onCourt?'Player coming in':'Player going out'}<select id="otherPlayer"><option value="">No other player (warn if lineup is not 5)</option>${other.map(q=>`<option value="${esc(q.id)}">#${esc(q.number)} ${esc(q.first)} ${esc(q.last)}</option>`).join('')}</select></label><label>Official clock<input id="subTime" value="${formatTime(d.clock.seconds)}" pattern="[0-9]{1,2}:[0-5][0-9]" required></label><button class="primary">Record substitution</button></form>`);$('#subForm').onsubmit=e=>{e.preventDefault();try{if(state.clock.final)throw Error('Undo finalization before changing the lineup.');const seconds=readClock($('#subTime').value,d.clock.period),q=$('#otherPlayer').value;const events=[{type:p.onCourt?'PLAYER_OUT':'PLAYER_IN',playerId:p.id,team:p.team,period:d.clock.period,clock:seconds}];if(q)events.push({type:p.onCourt?'PLAYER_IN':'PLAYER_OUT',playerId:q,team:p.team,period:d.clock.period,clock:seconds});if(act({events,clock:{seconds},label:'Substitution recorded'}).ok)$('#dialog').close();}catch(err){feedback(err.message,true);}};}
const headers=['Player','MIN','PTS','FG','2PT','3PT','FT','OREB','DREB','REB','AST','STL','BLK','TO','PF'];
function statsTable(rows){return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>{const s=r.stats;return `<tr><td>${esc(r.label)}</td><td>${formatTime(r.min)}</td><td>${s.pts}</td><td>${s.fgm}/${s.fga}</td><td>${s.twoM}/${s.twoA}</td><td>${s.threeM}/${s.threeA}</td><td>${s.ftm}/${s.fta}</td>${['oreb','dreb','reb','ast','stl','blk','to','pf'].map(k=>`<td>${s[k]}</td>`).join('')}</tr>`;}).join('')}</tbody></table>`;}
function renderBox(){const d=derive(state),periods=Array.from({length:Math.max(d.settings.periods,d.clock.period)},(_,i)=>i+1),rows=d.roster.filter(p=>p.team===boxTeam).map(p=>{const pl=d.players[p.id];return {label:`#${p.number} ${p.first} ${p.last}`,min:boxPeriod==='all'?pl.minutes:pl.periodMinutes[boxPeriod]||0,stats:boxPeriod==='all'?pl.stats:pl.periodStats[boxPeriod]||emptyStats()};}),total=boxPeriod==='all'?d.totals[boxTeam]:d.periodTotals[boxPeriod]?.[boxTeam]||emptyStats();rows.push({label:'TEAM TOTAL',min:rows.reduce((a,r)=>a+r.min,0),stats:total});const pct=(m,a)=>a?`${(100*m/a).toFixed(1)}%`:'—';$('#box').innerHTML=`<div class="sectionhead"><h2>${d.clock.final?'Final box score':'Live box score'}</h2><div class="actions"><select id="boxTeam" aria-label="Team"><option value="home">${esc(d.settings.home)}</option><option value="away">${esc(d.settings.away)}</option></select><select id="boxPeriod" aria-label="Period"><option value="all">Full game</option>${periods.map(p=>`<option value="${p}">${periodLabel(p,d.settings)}</option>`).join('')}</select></div></div><div class="tablewrap"><table><thead><tr><th>Score by period</th>${periods.map(p=>`<th>${periodLabel(p,d.settings)}</th>`).join('')}<th>TOTAL</th></tr></thead><tbody>${['home','away'].map(t=>`<tr><td>${esc(d.settings[t])}</td>${periods.map(p=>`<td>${d.periodTotals[p]?.score[t]||0}</td>`).join('')}<td><strong>${d.score[t]}</strong></td></tr>`).join('')}</tbody></table></div><div class="tablewrap" style="margin-top:20px">${statsTable(rows)}</div><p class="muted" style="margin:14px 0">FG ${pct(total.fgm,total.fga)} · 3PT ${pct(total.threeM,total.threeA)} · FT ${pct(total.ftm,total.fta)} · Timeouts used: ${d.settings.timeouts-d.timeouts[boxTeam]}. Score adjustments are separate from player points.</p><div class="actions"><button id="exportCSV">Export box score CSV</button><button id="printBox">Print</button>${reportControls()}<button id="exportGameBox">Export complete game</button></div>`;$('#boxTeam').value=boxTeam;$('#boxPeriod').value=boxPeriod;$('#boxTeam').onchange=e=>{boxTeam=e.target.value;renderBox();};$('#boxPeriod').onchange=e=>{boxPeriod=e.target.value;renderBox();};bindReports();$('#printBox').onclick=()=>window.print();$('#exportGameBox').onclick=exportGame;$('#exportCSV').onclick=()=>exportCSV(d);}
function exportCSV(d){const lines=[['Team','Period',...headers]];for(const team of ['home','away'])for(const period of ['all',...Array.from({length:Math.max(d.clock.period,d.settings.periods)},(_,i)=>i+1)]){const rows=d.roster.filter(p=>p.team===team).map(p=>d.players[p.id]);for(const p of [...rows,{first:'TEAM',last:'TOTAL',number:'',stats:d.totals[team],minutes:rows.reduce((n,p)=>n+p.minutes,0),periodStats:Object.fromEntries(Object.entries(d.periodTotals).map(([q,t])=>[q,t[team]])),periodMinutes:Object.fromEntries(Array.from({length:Math.max(d.clock.period,d.settings.periods)},(_,i)=>[i+1,rows.reduce((n,p)=>n+(p.periodMinutes[i+1]||0),0)]))}]){const s=period==='all'?p.stats:p.periodStats[period]||emptyStats();lines.push([d.settings[team],period==='all'?'TOTAL':periodLabel(period,d.settings),`${p.number} ${p.first} ${p.last}`.trim(),formatTime(period==='all'?p.minutes:p.periodMinutes[period]||0),s.pts,`${s.fgm}/${s.fga}`,`${s.twoM}/${s.twoA}`,`${s.threeM}/${s.threeA}`,`${s.ftm}/${s.fta}`,...['oreb','dreb','reb','ast','stl','blk','to','pf'].map(k=>s[k])]);}}lines.push([],['Team','Final score','Timeouts used'],...['home','away'].map(t=>[d.settings[t],d.score[t],d.settings.timeouts-d.timeouts[t]]));download('courtside-box-score.csv','text/csv',lines.map(row=>row.map(v=>{let x=String(v);if(/^[=+@-]/.test(x))x="'"+x;return '"'+x.replaceAll('"','""')+'"';}).join(',')).join('\r\n'));}
function renderTimeline(){const d=derive(state);$('#timeline').innerHTML=`<div class="sectionhead"><h2>Event timeline <span class="muted">${d.timeline.length} events</span></h2><button id="exportTimeline">Export game + ledger</button></div><div class="panel">${[...d.timeline].reverse().map(e=>`<div class="timelineRow"><div class="stamp">${periodLabel(e.period,d.settings)}<small>${e.awaitingClock?'Awaiting time':formatTime(e.clock)}${e.estimatedTime?' · estimated':''}</small></div><div><strong>${esc(describe(e,d))}</strong><small>${esc(e.raw)} · ${e.scoreAfter.home}–${e.scoreAfter.away}</small></div>${['SHOT','STAT','PLAYER_IN','PLAYER_OUT','TEAM_TIMEOUT','TIMEOUT_RETURN','SCORE_CORRECTION'].includes(e.type)?`<button data-edit="${esc(e.id)}">Correct</button>`:''}</div>`).join('')||'<p class="muted">Plays are spaced evenly between reported times. Estimated times can be corrected.</p>'}</div>`;$('#exportTimeline').onclick=exportGame;$('#timeline').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editEvent(b.dataset.edit));}

function renderSetup(){const d=derive(state),s=d.settings;$('#setup').innerHTML=`<div class="grid2"><div class="panel"><h2>Game settings</h2><form id="settingsForm"><div class="fields"><label>Your team<input name="home" value="${esc(s.home)}" required maxlength="60"></label><label>Opponent<input name="away" value="${esc(s.away)}" required maxlength="60"></label><label>Your designation<select name="designation"><option value="home">Home</option><option value="away">Away</option></select></label><label>Regulation periods<input name="periods" type="number" min="1" max="12" value="${s.periods}" required></label><label>Period length (minutes)<input name="length" type="number" min="1" max="60" value="${s.length/60}" required></label><label>Overtime (minutes)<input name="overtime" type="number" min="1" max="20" value="${s.overtime/60}" required></label><label>Foul-out limit<input name="foulLimit" type="number" min="1" max="10" value="${s.foulLimit}" required></label><label>Timeouts per team<input name="timeouts" type="number" min="0" max="20" value="${s.timeouts}" required></label></div><div class="actions"><button class="primary" ${d.clock.started?'disabled':''}>Save settings</button></div>${d.clock.started?'<p class="muted">Settings are locked after tip-off.</p>':''}</form><label class="review"><span><input id="autoAssists" type="checkbox" ${s.autoAssists?'checked':''}> Automatic assists from passing chains</span></label><h3>Game files</h3><p class="muted">Games and collections save to your account. Offline changes stay on this device until synced. Export a backup whenever you need a separate copy.</p><div class="actions"><button id="backup">Export game</button><button id="importGame">Import game</button><button id="newGame">New game</button></div><input type="file" id="gameFile" accept=".json,application/json" hidden><h3>Opponent scoring</h3><p class="muted">Use team-only entries when you do not have their roster.</p><div class="actions">${[['+2',2,1],['+3',3,1],['FT made',1,1],['2PT miss',2,0],['3PT miss',3,0],['FT miss',1,0]].map((v,i)=>`<button data-opponent="${i}">${v[0]}</button>`).join('')}</div></div><div class="panel"><h2>Roster & starting five</h2><p class="muted" style="margin-top:10px">Choose five starters before tip-off. Names, nicknames, aliases, and jersey numbers all identify the same player.</p><form id="playerForm"><div class="fields"><label>Jersey number<input name="number" inputmode="numeric" pattern="[0-9]{1,3}" placeholder="43" required></label><label>Team<select name="team"><option value="home">${esc(s.home)}</option><option value="away">${esc(s.away)}</option></select></label><label>First name<input name="first" placeholder="Cayden" required maxlength="40"></label><label>Last name<input name="last" placeholder="Smith" maxlength="40"></label><label>Nickname<input name="nickname" maxlength="40"></label><label>Voice aliases (comma separated)<input name="aliases" placeholder="Cay, Caden" maxlength="250"></label></div><div class="actions"><button class="primary">Add player</button><button type="button" id="importRoster">Import roster CSV</button><input id="rosterFile" type="file" accept=".csv,text/csv" hidden></div></form><p class="muted" style="margin-top:12px">CSV columns: number, first, last, nickname, aliases, team. Use semicolons between aliases; team is home (your team) or away (opponent).</p><div id="rosterList">${d.roster.map(p=>`<div class="rosterRow"><label><input type="checkbox" data-starter="${esc(p.id)}" ${d.players[p.id].onCourt?'checked':''}> <strong>#${esc(p.number)} ${esc(p.first)} ${esc(p.last)}</strong><small class="muted"> ${esc(s[p.team])}</small></label><button data-roster-edit="${esc(p.id)}">Edit</button></div>`).join('')}</div><div class="actions"><button id="saveStarters" class="primary">${d.clock.started?'Update on-court lineup':'Save starting five'}</button></div></div></div>`;$('#settingsForm [name=designation]').value=s.designation;$('#settingsForm').onsubmit=e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));for(const k of ['periods','length','overtime','foulLimit','timeouts'])data[k]=+data[k];data.length*=60;data.overtime*=60;data.autoAssists=s.autoAssists;act(configPlan(data,state));renderSetup();}catch(err){feedback(err.message,true);}};$('#autoAssists').onchange=e=>{if(state.clock.final){e.target.checked=s.autoAssists;return feedback('This game is finalized.',true);}act({events:[{type:'CONFIG',settings:{...derive(state).settings,autoAssists:e.target.checked}}],label:'Automatic assists '+(e.target.checked?'on':'off')});};$('#playerForm').onsubmit=e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));data.aliases=data.aliases.split(',').map(v=>v.trim()).filter(Boolean);act(playerPlan(data,state));renderSetup();}catch(err){feedback(err.message,true);}};$('#saveStarters').onclick=()=>{if(state.clock.final)return feedback('Undo finalization before changing the lineup.',true);const ids=[...$('#rosterList').querySelectorAll('input:checked')].map(i=>i.dataset.starter),events=[];for(const team of ['home','away']){const players=ids.filter(id=>d.players[id].team===team);if(team==='home'&&players.length!==5)return feedback('Choose exactly five players for your team.',true);if(players.length&&players.length!==5)return feedback('Choose five opponent starters, or leave their lineup empty.',true);if(players.length||d.lineups[team].size)events.push({type:'STARTERS',team,players});}act({events,label:'Lineup saved'});};$('#rosterList').querySelectorAll('[data-roster-edit]').forEach(b=>b.onclick=()=>editRoster(b.dataset.rosterEdit));$('#backup').onclick=exportGame;$('#importGame').onclick=()=>$('#gameFile').click();$('#gameFile').onchange=importGame;$('#newGame').onclick=()=>libraryUI?.newGame();$('#importRoster').onclick=()=>$('#rosterFile').click();$('#rosterFile').onchange=importRoster;$('#setup').querySelectorAll('[data-opponent]').forEach(b=>b.onclick=()=>{const a=[[2,1],[3,1],[1,1],[2,0],[3,0],[1,0]][+b.dataset.opponent];if(state.clock.final)return feedback('Undo finalization before changing stats.',true);act({events:[{type:'SHOT',team:'away',value:a[0],made:a[1],attempts:1,points:a[0]*a[1]}],label:'Opponent shot recorded'});});}
function editRoster(id){const d=derive(state),p=d.players[id];showDialog(`<h2>Edit #${esc(p.number)}</h2><form id="editRoster" class="fields">${['number','first','last','nickname'].map(k=>`<label>${k}<input name="${k}" value="${esc(p[k])}" ${['number','first'].includes(k)?'required':''}></label>`).join('')}<label>Aliases<input name="aliases" value="${esc(p.aliases.join(', '))}"></label><button class="primary">Save player</button></form>`);$('#editRoster').onsubmit=e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));values.aliases=values.aliases.split(',').map(s=>s.trim()).filter(Boolean);if(!/^\d{1,3}$/.test(values.number)||d.roster.some(q=>q.id!==id&&q.team===p.team&&q.number===values.number))throw Error('Use a unique jersey number.');const roster=d.roster.map(q=>q.id===id?{...q,...values}:q);act({events:[{type:'ROSTER',roster}],label:'Roster updated'});renderSetup();$('#dialog').close();}catch(err){feedback(err.message,true);}};}
function parseCSV(text){const rows=[];let row=[],v='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(v.trim());v='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v.trim());if(row.some(Boolean))rows.push(row);row=[];v='';}else v+=c;}if(quoted)throw Error('CSV has an unclosed quote.');row.push(v.trim());if(row.some(Boolean))rows.push(row);return rows;}
async function importRoster(e){try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('Roster file is too large.');const rows=parseCSV(await f.text()),header=rows.shift().map(h=>h.replace(/^\uFEFF/,'').toLowerCase());if(!header.includes('number')||!header.includes('first'))throw Error('CSV needs number and first column headers.');const temp=structuredClone(state),events=[];for(const row of rows){const p=Object.fromEntries(header.map((k,i)=>[k,row[i]||'']));p.team=p.team||'home';p.aliases=(p.aliases||'').split(';').map(s=>s.trim()).filter(Boolean);const plan=playerPlan(p,temp);events.push(...plan.events);applyPlan(temp,plan);}act({events,label:`Imported ${events.length} players`},'Roster CSV import');renderSetup();}catch(err){feedback(err.message,true);}}
function download(name,type,text){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportGame(){materializeClock(state);const d=derive(state);download(`courtside-${new Date().toISOString().slice(0,10)}.json`,'application/json',JSON.stringify({...state,report:{score:d.score,players:d.players,periods:d.periodTotals,timeouts:d.timeouts,timeline:d.timeline}},null,2));}
async function importGame(e){try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('Game backup is too large.');const candidate=validateImport(JSON.parse(await f.text()));showDialog('<h2>Replace the current game?</h2><p>Your current game will download as a backup before the imported game is opened. Its clock will be paused.</p><button id="confirmImport" class="primary">Back up & import game</button>',()=>{$('#confirmImport').onclick=()=>{exportGame();stopMic();state=libraryUI?libraryUI.prepareImport(candidate):candidate;state.clock={...state.clock,running:false,wall:Date.now()};pending=[];selected=null;save();render();renderSetup();renderPending();$('#dialog').close();};});}catch(err){feedback(err.message,true);}}
function showDialog(html,ready){$('#dialogContent').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();ready?.();}$('#closeDialog').onclick=()=>$('#dialog').close();
function readClock(text,p){const m=text.match(/^(\d{1,2}):([0-5]\d)$/);if(!m)throw Error('Use minutes:seconds, such as 4:23.');const sec=+m[1]*60+ +m[2];if(sec>lengthFor(p,derive(state).settings))throw Error('Clock exceeds the configured period length.');return sec;}
$('#syncClock').onclick=()=>{const d=derive(state);showDialog(`<h2>Match the official scoreboard</h2><form id="clockForm" class="fields"><label>Period<input id="clockPeriod" type="number" min="1" max="${d.settings.periods+20}" value="${d.clock.period}" required></label><label>Time remaining<input id="clockValue" value="${formatTime(d.clock.seconds)}" pattern="[0-9]{1,2}:[0-5][0-9]" required></label><label>Your score<input id="ourScore" type="number" min="0" value="${d.score.home}" required></label><label>Opponent score<input id="theirScore" type="number" min="0" value="${d.score.away}" required></label><button class="primary">Synchronize</button></form>`);$('#clockForm').onsubmit=e=>{e.preventDefault();try{if(state.clock.final)throw Error('Undo finalization before changing the clock.');const period=+$('#clockPeriod').value,seconds=readClock($('#clockValue').value,period),events=[{type:'CLOCK_SYNC',period,clock:seconds}];for(const [team,selector] of [['home','#ourScore'],['away','#theirScore']])if(+$(selector).value!==d.score[team])events.push({type:'SCORE_CORRECTION',team,absolute:+$(selector).value,period,clock:seconds});act({events,clock:{period,seconds},label:'Scoreboard synchronized'});$('#dialog').close();}catch(err){feedback(err.message,true);}};};
$('#toggleClock').onclick=()=>command('tip off');$('#timeoutHome').onclick=()=>command('My team timeout');$('#timeoutAway').onclick=()=>command('Opponent timeout');$('#undo').onclick=()=>{try{undo(state);save();render();if(view==='setup')renderSetup();feedback('Undid the last command.');}catch(e){feedback(e.message,true);}};$('#endGame').onclick=()=>command('end game');$('#commandForm').onsubmit=e=>{e.preventDefault();const result=command($('#command').value);if(result.ok)$('#command').value='';};
function setMic(label,on=false){$('#micState').textContent=label;$('#micState').className='badge'+(on?' on':'');$('#listen').textContent=wantsMic?(on?'Listening…':label==='RECONNECTING'?'Reconnecting…':'Starting…'):'● Start listening';$('#listen').disabled=wantsMic;}
function speechNotice(message=''){const el=$('#speechNotice');el.hidden=!message;el.textContent=message;el.className='warning';}
function voiceConnectionHelp(){showDialog(`<h2>Voice connection</h2><p>The microphone and speech recognition are separate. A moving meter means the app is receiving sound. Words appear only after the browser’s speech service processes it.</p><p>A speech “network” error does not prove that Ethernet or Wi-Fi is disconnected. The recognition service can be blocked or unavailable while other websites work.</p><p>Try this site in the standalone <strong>Google Chrome</strong> app. If you are viewing it inside another app, copy this address into Chrome:</p><label>Site address<input id="voiceSiteURL" readonly value="${esc(location.origin)}"></label><button id="copyVoiceURL">Copy site address</button><p>If <strong>Enable offline speech</strong> is available, it downloads English recognition to your device so speech does not need the online recognition service afterward. Otherwise, check whether a VPN, firewall, or browser setting is blocking speech services.</p><p>Plays spoken during a connection failure are not saved unless they appear in the transcript. Type any missed plays into the command box.</p>`);$('#copyVoiceURL').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin);$('#copyVoiceURL').textContent='Copied — paste into Chrome';}catch{$('#voiceSiteURL').select();}};}
async function screenAwake(){try{if('wakeLock' in navigator&&document.visibilityState==='visible')wake=await navigator.wakeLock.request('screen');}catch{}}
async function startMic(retrying=false){
 if(wantsMic)return;
 const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!Recognition){speechNotice('Speech recognition is unavailable in this browser. Open this site in standalone Chrome. Test mic and typing still work.');return;}
 if(!window.isSecureContext){feedback('Voice needs a secure HTTPS link. Open the published app in Chrome.',true);return;}
 wantsMic=true;if(!retrying){micErrors=0;speechNotice();}screenAwake();const session=new Recognition();mic=session;session.lang='en-US';session.continuous=true;session.interimResults=true;session.maxAlternatives=1;setMic('STARTING');
 let mode='online',hadNetworkError=false;
 function scheduleRetry(){if(mic!==session||!wantsMic||document.hidden)return;clearTimeout(restartTimer);clearTimeout(retryWatchdog);setMic('RECONNECTING');const delay=hadNetworkError?retryDelay(micErrors):750;restartTimer=setTimeout(()=>{if(mic!==session||!wantsMic)return;mic=null;try{session.abort();}catch{}wantsMic=false;startMic(true);},delay);}
 session.onstart=()=>{if(mic===session&&wantsMic){setMic(mode==='offline'?'LISTENING · OFFLINE':'LISTENING',true);if(!micErrors)speechNotice();}};
 session.onresult=e=>{if(mic!==session||!wantsMic)return;micErrors=0;hadNetworkError=false;speechNotice();for(let i=e.resultIndex;i<e.results.length;i++){const r=e.results[i];if(r.isFinal)receiveVoice(r[0].transcript.trim(),r[0].confidence??0);else $('#heard').textContent=`Hearing: ${r[0].transcript}`;}};
 session.onerror=e=>{
  if(mic!==session||!wantsMic||e.error==='no-speech'||e.error==='aborted')return;
  if(e.error==='network'){
   hadNetworkError=true;micErrors++;setMic('RECONNECTING');
   if(micErrors>=5){stopMic('MIC TEST ONLY',true);speechNotice('The speech service is still unreachable. The mic meter remains available, but speech is not being transcribed. Try Enable offline speech, or Voice connection help to open this site in standalone Chrome. Your saved game is safe.');return;}
   speechNotice(`The browser’s speech service lost its connection. This does not mean your Ethernet or Wi-Fi is down. Retrying in ${retryDelay(micErrors)/1000} seconds. Repeat any play that did not appear in the transcript.`);
   // Most browsers follow error with end; this watchdog also recovers if end never arrives.
   clearTimeout(retryWatchdog);retryWatchdog=setTimeout(scheduleRetry,1500);return;
  }
  stopMic('VOICE UNAVAILABLE',e.error==='service-not-allowed');
  speechNotice(e.error==='not-allowed'?'Microphone permission was denied. Allow microphone access in Chrome site settings.':e.error==='service-not-allowed'?'This browser cannot use its speech service. Open Voice connection help and try standalone Chrome.':e.error==='language-not-supported'?'English speech recognition is unavailable. Try enabling offline speech or use another supported browser.':`Speech recognition stopped (${e.error}). Use Test mic to check the input, or Voice connection help.`);
 };
 session.onend=()=>{if(mic===session&&wantsMic)scheduleRetry();};
 try{const prepared=await prepareRecognition(Recognition,session);if(mic!==session||!wantsMic)return;mode=prepared.mode;$('#speechMode').textContent=mode==='offline'?'Speech recognition: on this device':'Speech recognition: browser service';$('#offlineSpeech').hidden=typeof Recognition.install!=='function'||!['downloadable','downloading','available'].includes(prepared.local);$('#offlineSpeech').textContent=prepared.local==='available'?'Use offline speech':'Enable offline speech';await micInput.start(session);}catch(e){if(mic!==session)return;stopMic();speechNotice(e.message||'Microphone could not start. Use Test mic to check it.');}
}
function stopMic(label='MIC OFF',keepMeter=false){if(typeof voiceBatch!=='undefined'&&voiceBatch){clearTimeout(voiceBatchTimer);$('#command').value=voiceBatch.raw;voiceBatch=null;}idleMicLabel=label;wantsMic=false;clearTimeout(restartTimer);clearTimeout(retryWatchdog);const old=mic;mic=null;try{old?.abort();}catch{}if(!keepMeter){micInput?.release();speechNotice();}wake?.release().catch(()=>{});wake=null;setMic(label);}
micInput=createMicInput({showDialog,feedback,stopMic,startMic,isListening:()=>wantsMic});$('#switchMic').onclick=()=>micInput.open();$('#voiceHelp').onclick=voiceConnectionHelp;$('#testMic').onclick=async()=>{stopMic();setMic('MIC TEST ONLY');try{await micInput.test();feedback('Speak and watch the input meter. Tap Stop to release the microphone.');}catch(e){stopMic();speechNotice(e.message);}};
$('#offlineSpeech').onclick=async()=>{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(typeof Recognition?.install!=='function')return;stopMic();const b=$('#offlineSpeech');b.disabled=true;speechNotice('Downloading English speech recognition to this device…');try{const ok=await Recognition.install({langs:['en-US'],processLocally:true});if(!ok)throw Error('English speech could not be installed. Try standalone Chrome and try again.');const probe=new Recognition(),check=await prepareRecognition(Recognition,probe);if(check.mode!=='offline')throw Error('The download is not ready yet. Try again after it finishes.');speechNotice('Offline speech is ready. Tap Start listening.');$('#speechMode').textContent='Offline speech ready';b.textContent='Use offline speech';}catch(e){speechNotice(e.message||'Offline speech could not be enabled in this browser.');}finally{b.disabled=false;}};$('#listen').onclick=()=>startMic();$('#pauseMic').onclick=()=>stopMic('PAUSED');$('#stopMic').onclick=()=>stopMic();document.addEventListener('visibilitychange',()=>{if(document.hidden){if(wantsMic||micInput.active()){stopMic();feedback('Listening paused while the app was hidden. Tap Start listening when you return.');}materializeClock(state);save();}});window.addEventListener('pagehide',()=>{stopMic();materializeClock(state);save();});window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{stopMic();state=validateImport(JSON.parse(e.newValue));render();feedback('Game updated from another tab. Use one tab at a time for recording.');}catch{}}});
$('#help').onclick=()=>showDialog(`<h2>Courtside, on PC or Pixel</h2><p>Open the published link in Chrome. On a Pixel, use Chrome’s menu → <strong>Add to Home screen → Install</strong>. On PC, use Chrome’s install icon when available.</p><p>Add your roster, save five starters, then tap <strong>Start listening</strong> and allow microphone access. Keep this app visible and the phone unlocked. Voice may need an internet connection; manual controls and local saving work offline after the app has loaded.</p><p>Say a full sequence of plays. Each clear action is recorded in order. Examples:</p><ul><li>“12 passes to 45 to 16. 16 shoots and scores on the two point line.”</li><li>“43 launches one from downtown and airballs it.”</li><li>“43 misses the layup, gets his own rebound and puts it back in.”</li><li>“43 shoots the three” or “43 A3,” then “He scored” or “She missed.”</li><li>“Opp,” “opponet,” or “enemy,” then “They stole the ball” or “They scored.”</li><li>“Moving onto the second quarter.”</li><li>Say your configured opponent’s name: “Woodland scores a three.”</li><li>“Rebound” goes to your team. Name a player for individual credit, or say “opponent rebound” for their team.</li><li>“Tip off has happened.”</li><li>“43 made a three.” / “12 assist.”</li><li>“43 one for two.” / “43 defensive rebound.”</li><li>“43 out, Mason in, Q2 4:23.”</li><li>“43 out, Mason in. Now it’s Q2 3:43.”</li><li>“My team timeout.” / “Give us one timeout back.”</li><li>“That was Mason.” / “Change that three to a two.”</li><li>“Correction Mason actually entered at Q2 4:33.”</li><li>“Undo last.” / “End second quarter.”</li><li>“Start third quarter.” / “Same five.”</li><li>“End game.” then “Confirm.”</li></ul><p>Low-confidence commands wait for confirmation. Enable <strong>Review every voice command</strong> in a noisy gym. Bench players must check in before recording actions. End game offers an automatic team or player PDF; download another copy from Box score. Unknown commands never change stats. Opponent players need “opponent” before their name or number.</p><p>Minutes use period and game-clock entry/exit intervals. The clock never counts down. Plays and substitutions appear immediately and wait for your next time update. Say “now it’s Q2 3:43” to spread waiting plays evenly over the time since your last update and recalculate minutes. Estimated times are labeled; each substitution group shares one time. Give another timestamp whenever you need a more precise entry or exit time.</p><p>Create seasons from <strong>Games & collections → New collection</strong>. Use <strong>New game</strong> to choose a collection, speak or type an opponent and date, and optionally set a start time. Completed games remain in their collection. Games save to your account for access on your signed-in devices; offline changes sync when connected. Record a game on one device at a time. Export a backup for a separate copy. Browser speech recognition may send audio to its recognition service; Courtside does not record or store audio.</p>${badBackup?'<button id="recover" class="primary">Download unreadable saved game</button><button id="clearRecovery">Start fresh after recovery</button>':''}`,()=>{if($('#recover'))$('#recover').onclick=()=>download('courtside-recovery.json','application/json',badBackup);if($('#clearRecovery'))$('#clearRecovery').onclick=()=>{download('courtside-recovery.json','application/json',badBackup);badBackup=null;save();render();$('#dialog').close();};});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
const context=document.modelContext;if(context?.registerTool){const controller=new AbortController();const tools=[{name:'read_basketball_game',title:'Read basketball game',description:'Read score, official-clock player minutes, lineup and warnings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>{const d=derive(state);return {score:d.score,clock:d.clock,players:Object.values(d.players).map(p=>({id:p.id,number:p.number,name:p.first+' '+p.last,onCourt:p.onCourt,minutes:p.minutes,stats:p.stats})),warnings:d.warnings};}},{name:'record_basketball_command',title:'Record basketball command',description:'Record one basketball command through the same parser and confirmation flow as the visible input. Returns pending when confirmation is required.',inputSchema:{type:'object',properties:{command:{type:'string',maxLength:2000}},required:['command'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input.command!=='string')throw Error('command must be a string');return command(input.command);}}];for(const tool of tools)try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
async function bootAccount(){accountUser=await getAccount({beforeLogout:async()=>{stopMic();try{await libraryUI?.flush();}catch{}}});if(!accountUser)return;KEY='courtside.game.v1.'+accountUser.id;try{let data=localStorage.getItem(KEY);if(!data&&accountUser.legacyLinked){data=localStorage.getItem('courtside.game.v1');if(data){localStorage.setItem(KEY,data);localStorage.removeItem('courtside.game.v1');}}if(data)state=validateImport(JSON.parse(data));}catch{saveError='Saved game could not be opened. Export the recovery copy in Help.';badBackup=localStorage.getItem(KEY);}render();if(saveError)feedback(saveError,true);
libraryUI=createLibraryUI({getAccountId:()=>accountUser.id,getState:()=>state,startRecognition:async r=>{await prepareRecognition(window.SpeechRecognition||window.webkitSpeechRecognition,r);return micInput.start(r);},releaseRecognition:()=>micInput.release(),writeLocal,exportGame,stopMic,render,setView,feedback,showDialog,replaceState(next){state=next;state.speechContext={};$('#understood').hidden=true;selected=null;pending=[];boxPeriod='all';$('#quick').hidden=true;renderPending();}});}
bootAccount();
function editEvent(id){const d=derive(state),e=d.timeline.find(e=>e.id===id);showDialog(`<h2>Correct event</h2><p>${esc(describe(e,d))}</p><form id="editEvent" class="fields"><label>Period<input id="editPeriod" type="number" min="1" max="${d.settings.periods+20}" value="${e.period}" required></label><label>Game clock<input id="editClock" value="${formatTime(e.clock)}" required pattern="[0-9]{1,2}:[0-5][0-9]"></label>${e.playerId?`<label>Player<select id="editPlayer">${d.roster.map(p=>`<option value="${esc(p.id)}" ${p.id===e.playerId?'selected':''}>${esc(d.settings[p.team])}: #${esc(p.number)} ${esc(p.first)}</option>`).join('')}</select></label>`:''}${e.type==='SHOT'?`<label>Shot value<select id="editValue"><option value="1">Free throw</option><option value="2">Two point</option><option value="3">Three point</option></select></label><label>Made<input id="editMade" type="number" min="0" max="3" value="${e.made}" required></label><label>Attempts<input id="editAttempts" type="number" min="1" max="3" value="${e.attempts}" required></label>`:''}${e.type==='STAT'?`<label>Stat<select id="editStat">${['oreb','dreb','ast','stl','blk','to','pf'].map(s=>`<option value="${s}" ${e.stat===s?'selected':''}>${s.toUpperCase()}</option>`).join('')}</select></label>`:''}${e.type==='SCORE_CORRECTION'?`<label>${e.absolute!==undefined?'Corrected score':'Point adjustment'}<input id="editScore" type="number" value="${e.absolute??e.delta}" required></label>`:''}<div class="actions"><button class="primary">Save correction</button><button type="button" id="removeEvent">Remove event</button></div></form><p class="muted">Corrections recalculate the box score and playing intervals. Original records stay in the exported ledger.</p>`);if($('#editValue'))$('#editValue').value=e.value;$('#editEvent').onsubmit=ev=>{ev.preventDefault();try{const period=+$('#editPeriod').value,clock=readClock($('#editClock').value,period),values={period,clock,awaitingClock:false,estimatedTime:false};if($('#editPlayer')){values.playerId=$('#editPlayer').value;values.team=d.players[values.playerId].team;}if($('#editValue')){values.value=+$('#editValue').value;values.made=+$('#editMade').value;values.attempts=+$('#editAttempts').value;if(values.made>values.attempts)throw Error('Made cannot exceed attempts.');values.points=values.value*values.made;}if($('#editStat'))values.stat=$('#editStat').value;if($('#editScore'))values[e.absolute!==undefined?'absolute':'delta']=+$('#editScore').value;const patches=[{id,values}];if(['PLAYER_IN','PLAYER_OUT'].includes(e.type))for(const other of d.timeline.filter(x=>x.id!==id&&['PLAYER_IN','PLAYER_OUT'].includes(x.type)&&x.transactionId===e.transactionId&&(!e.subPair||x.subPair===e.subPair)))patches.push({id:other.id,values:{period,clock,awaitingClock:false,estimatedTime:false}});act({events:[{type:'PATCH',patches}],label:'Event corrected'},'Manual correction');$('#dialog').close();}catch(err){feedback(err.message,true);}};$('#removeEvent').onclick=()=>{act({events:[{type:'PATCH',patches:[{id,values:{removed:true}}]}],label:'Event removed'},'Manual removal');$('#dialog').close();};}

function reportControls(ending=false){return `<label>${ending?'Automatic PDF after ending':'PDF report'}<select class="pdfScope"><option value="team">Whole team</option>${derive(state).roster.filter(p=>p.team==='home').map(p=>`<option value="${esc(p.id)}">#${esc(p.number)} ${esc(p.first)} ${esc(p.last)}</option>`).join('')}${ending?'<option value="off">Do not download automatically</option>':''}</select></label>${ending?'':'<button class="downloadPDF primary">Download PDF</button>'}`;}
function bindReports(){document.querySelectorAll('.pdfScope').forEach(el=>{el.value=state.meta?.pdfScope||'team';if(!el.value)el.value='team';el.onchange=()=>{state.meta={...state.meta,pdfScope:el.value};save();};});document.querySelectorAll('.downloadPDF').forEach(b=>b.onclick=()=>makePDF(b.parentElement.querySelector('.pdfScope')?.value||'team'));}
function makePDF(scope){try{downloadReport(state,scope);feedback('PDF prepared. If the download did not start, use Download PDF in Box score.');}catch{feedback('PDF could not be generated. Try Download PDF again or use Print.',true);}}


function subPreview(plan){if(!plan.subPreview)return '';const d=derive(state),label=id=>{const p=d.players[id];return p?`#${esc(p.number)} ${esc(p.first)}`:'?';},v=plan.subPreview;return `<div class="subPreview"><p><strong>${periodLabel(plan.clock?.period??d.clock.period,d.settings)} ${formatTime(plan.clock?.seconds??d.clock.seconds)}</strong></p><p>OUT: ${v.out.map(label).join(', ')||'None'}</p><p>IN: ${v.in.map(label).join(', ')||'None'}</p><p>New lineup: ${v.five.map(label).join(', ')}</p>${v.valid?'':`<p class="warning">${v.five.length} players on court. Finish the substitution or confirm this temporary lineup.</p>`}</div>`;}
function receiveVoice(raw,confidence){
 const subLike=/\b(?:out|in|for|sub|swap|bench|sit|replaces?|enters?)\b|>/.test(raw.toLowerCase())&&!/\b(?:shoot|shoots|shot|score|scores|scored|made|makes|miss|misses|missed|pass|passes|rebound)\b/.test(raw.toLowerCase());
 if(pending[0]?.partialSub&&subLike){const prior=pending.shift();raw=prior.raw+' and '+raw;renderPending();}
 if(!subLike){if(voiceBatch)flushVoiceBatch();return command(raw,true,confidence);}
 if(voiceBatch){voiceBatch.raw+=' and '+raw;voiceBatch.confidence=Math.min(voiceBatch.confidence,confidence);}else voiceBatch={raw,confidence};
 $('#heard').textContent='Hearing substitution: '+voiceBatch.raw;clearTimeout(voiceBatchTimer);voiceBatchTimer=setTimeout(flushVoiceBatch,1000);
}
function flushVoiceBatch(){clearTimeout(voiceBatchTimer);const batch=voiceBatch;voiceBatch=null;if(!batch)return;try{const plan=parseCommand(batch.raw,state);if(plan.subPreview&&!plan.subPreview.valid){pending.push({...batch,plan,partialSub:true});renderPending();feedback('Waiting for the rest of the substitution. Say who comes in, or confirm the temporary lineup.');return;}command(batch.raw,true,batch.confidence);}catch(e){feedback(e.message,true);$('#command').value=batch.raw;}}
